mapper.select:
SELECT *
FROM TBL_FUND_TRANSFER

    DELETE_FLAG = 0

        AND ORG_ID = #{param.orgId}


        AND TRANSFER_NO LIKE CONCAT('%', #{param.transferNo}, '%')


        AND FROM_ACCOUNT_NUMBER LIKE CONCAT('%', #{param.fromAccount}, '%')


        AND TO_ACCOUNT_NUMBER LIKE CONCAT('%', #{param.toAccount}, '%')


        AND TRANSFER_STATUS = #{param.transferStatus}


        AND APPLY_DATE >= #{param.applyDateStart}


        AND APPLY_DATE <= #{param.applyDateEnd}


ORDER BY CREATED_TIME DESC
